package com.multistreamcammc;
import com.mojang.brigadier.arguments.StringArgumentType;import com.multistreamcammc.camera.*;import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;import net.fabricmc.fabric.api.networking.v1.*;import net.minecraft.command.argument.DimensionArgumentType;import net.minecraft.network.PacketByteBuf;import net.minecraft.server.command.*;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.server.world.ServerWorld;import net.minecraft.text.Text;import net.minecraft.util.Identifier;
public class MultiStreamCamMCMod implements ModInitializer{
 public static final String MOD_ID="multistreamcammc";public static final Identifier CAMERA_SYNC_PACKET=new Identifier(MOD_ID,"camera_sync"),CAMERA_REQUEST_PACKET=new Identifier(MOD_ID,"camera_request"),CAMERA_GOTO_PACKET=new Identifier(MOD_ID,"camera_goto");
 public void onInitialize(){CommandRegistrationCallback.EVENT.register((d,r,e)->d.register(CommandManager.literal("multistreamcam").requires(s->s.hasPermissionLevel(2)).then(CommandManager.literal("crear").then(CommandManager.argument("nombre",StringArgumentType.word()).executes(c->{var s=c.getSource();var p=s.getPlayer();String n=StringArgumentType.getString(c,"nombre");CameraState.get(s.getServer()).put(new CameraPoint(n,p.getWorld().getRegistryKey(),p.getBlockPos(),p.getYaw(),p.getPitch()));s.sendFeedback(()->Text.literal("Cámara creada: "+n),true);return 1;}))).then(CommandManager.literal("crear_en").then(CommandManager.argument("nombre",StringArgumentType.word()).then(CommandManager.argument("dimension",DimensionArgumentType.dimension()).executes(c->{var s=c.getSource();var p=s.getPlayer();ServerWorld w=DimensionArgumentType.getDimensionArgument(c,"dimension");String n=StringArgumentType.getString(c,"nombre");CameraState.get(s.getServer()).put(new CameraPoint(n,w.getRegistryKey(),p.getBlockPos(),p.getYaw(),p.getPitch()));return 1;})))).then(CommandManager.literal("ir").then(CommandManager.argument("nombre",StringArgumentType.word()).executes(c->gotoCamera(c.getSource(),StringArgumentType.getString(c,"nombre"))))).then(CommandManager.literal("eliminar").then(CommandManager.argument("nombre",StringArgumentType.word()).executes(c->{boolean ok=CameraState.get(c.getSource().getServer()).remove(StringArgumentType.getString(c,"nombre"));return ok?1:0;}))).then(CommandManager.literal("listar").executes(c->{var st=CameraState.get(c.getSource().getServer());st.getAll().forEach(x->c.getSource().sendFeedback(()->Text.literal(x.name()+" @ "+x.dimension().getValue()),false));return st.getAll().size();}))));ServerPlayNetworking.registerGlobalReceiver(CAMERA_REQUEST_PACKET,(server,player,h,buf,rs)->server.execute(()->sendCameras(player)));ServerPlayNetworking.registerGlobalReceiver(CAMERA_GOTO_PACKET,(server,player,h,buf,rs)->{String n=buf.readString();server.execute(()->gotoCamera(player.getCommandSource(),n));});}
 private static int gotoCamera(ServerCommandSource s,String n){var o=CameraState.get(s.getServer()).get(n);if(o.isEmpty())return 0;var c=o.get();ServerPlayerEntity p=s.getPlayer();ServerWorld w=s.getServer().getWorld(c.dimension());if(w==null)return 0;p.teleport(w,c.pos().getX()+.5,c.pos().getY(),c.pos().getZ()+.5,c.yaw(),c.pitch());return 1;}
 private static void sendCameras(ServerPlayerEntity p){PacketByteBuf out=PacketByteBufs.create();var cams=CameraState.get(p.getServer()).getAll();out.writeVarInt(cams.size());cams.forEach(c->{out.writeString(c.name());out.writeString(c.dimension().getValue().toString());out.writeBlockPos(c.pos());out.writeFloat(c.yaw());out.writeFloat(c.pitch());});ServerPlayNetworking.send(p,CAMERA_SYNC_PACKET,out);}
}
